using LittleLeo;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Events;

namespace Astrea;

[CreateAssetMenu(fileName = "EmpowerEffect", menuName = "Data/Battle/Effects/Empower Effect")]
public class EmpowerEffect : Effect
{
	[Header("Interaction Type")]
	[SerializeField]
	private BattleActionInteractionEnum battleActionInteractionEnum;

	[SerializeField]
	private bool doom;

	[SerializeField]
	[ShowIf("doom")]
	private OutbreakEffect outbreakEffect;

	[SerializeField]
	private bool waitFewFramesToApply;

	public BattleActionInteractionEnum BattleActionInteractionEnum => battleActionInteractionEnum;

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		ActivateEffect(effectAmount, effectOwner);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		ActivateEffect(effectAmount, effectOwner);
	}

	public override void EffectDecreased(int effectAmount, GameObject effectOwner)
	{
		ActivateEffect(effectAmount, effectOwner);
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		UnityAction unityAction = delegate
		{
			effectOwner.GetComponent<UnitEffects>().ToggleActionValueModifier(new ActionValueModifier(effectAmount, battleActionInteractionEnum));
		};
		if (waitFewFramesToApply)
		{
			InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, unityAction);
		}
		else
		{
			unityAction();
		}
		return effectAmount;
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().ToggleActionValueModifier(new ActionValueModifier(0, battleActionInteractionEnum));
		base.RemoveEffect(effectAmount, effectOwner);
		if (doom)
		{
			VFXHolder vFXInstanceFromVFXHoldersAndRemoveItFromList = ReferenceSingleton<VFXHandler>.Instance.GetVFXInstanceFromVFXHoldersAndRemoveItFromList(effectOwner, outbreakEffect);
			if (vFXInstanceFromVFXHoldersAndRemoveItFromList != null)
			{
				GameObject vFXInstance = vFXInstanceFromVFXHoldersAndRemoveItFromList.VFXInstance;
				vFXInstance.GetComponent<ParticleEmissionController>().SetActive(value: false);
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(vFXInstance, 2f);
			}
		}
	}

	public override void OnRemoveEffectEndOfBattle(int effectAmount, GameObject effectOwner)
	{
		RemoveEffect(effectAmount, effectOwner);
	}
}
